// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address sender, address target, bool emergency) public {
        vm.assume(sender != address(0));
        vm.assume(target != address(0));

        // Ensure the contract is configured
        c.endConfiguration();

        // We need to be able to call assertGovernanceApproved - it requires msg.sender == DAO or governed[msg.sender]
        // The DAO is address(this) from constructor, so we can use prank
        vm.prank(address(this));

        // Try calling assertGovernanceApproved - it will revert unless we have deposited tokens
        // But the key invariant is that configured remains true regardless
        // We use try/catch to handle expected reverts
        try c.assertGovernanceApproved(sender, target, emergency) {} catch {}

        assertTrue(c.configured());
    }
}

